  const pick = (strategy) => ordered.filter((t) => byId[t].strategy === strategy).slice(0, 3).map((t) => byId[t].short_label);
  const n26 = pick('nds2026'), n22 = pick('nds2022'), xc = pick('cross');
  const parts = [];
