  if (xc.length) parts.push('Also: ' + xc.join(', '));
  const primaryTag = ordered.find((t) => byId[t].strategy !== 'cross') || ordered[0];
  const group = primaryTag ? byId[primaryTag].group : 'Budget, Congress & Leadership';
