  if (!j || typeof j !== 'object') return [];
  const key = Object.keys(j).find((k) => /crs/i.test(k) && Array.isArray(j[k]));
  const arr = key ? j[key] : (Array.isArray(j.reports) ? j.reports : []);
  return arr.map((r) => {
