  for (const p of topics.priorities) {
    const h = p.keywords.filter((k) => kwMatch(text, k));
    if (h.length) hits[p.id] = h;
  }
  return hits;
}
function hasContext(text, topics) { return (topics.prefilter.context_terms || []).some((k) => kwMatch(text, k)); }
