/* ---------------- strategy alignment ---------------- */
function tagCounts(members) {
  const c = {};
  for (const m of members) for (const t of [...m.relevance.nds2026_tags, ...m.relevance.nds2022_tags]) c[t] = (c[t] || 0) + 1;
  return c;
